#pragma once
struct MultiMapping {
 static void clamp(SfzRegion& r){r.low=juce::jlimit(0,127,r.low);r.high=juce::jlimit(r.low,127,r.high);r.root=juce::jlimit(0,127,r.root);r.lovel=juce::jlimit(0,127,r.lovel);r.hivel=juce::jlimit(r.lovel,127,r.hivel);if(r.source){int n=r.source->buffer.getNumSamples();r.start=juce::jlimit(0,n-1,r.start);r.end=juce::jlimit(r.start+1,n,r.end<0?n:r.end);r.loopStart=juce::jlimit(r.start,r.end-1,r.loopStart);r.loopEnd=juce::jlimit(r.loopStart+1,r.end,r.loopEnd<0?r.end:r.loopEnd);}}
 static void autoMap(std::vector<SfzRegion>& rows){std::set<int> notes;for(auto& r:rows)notes.insert(r.root);std::vector<int> roots(notes.begin(),notes.end());for(auto& r:rows){int index=(int)(std::find(roots.begin(),roots.end(),r.root)-roots.begin());r.low=index==0?0:(roots[index-1]+r.root)/2+1;r.high=index+1==(int)roots.size()?127:(r.root+roots[index+1])/2;clamp(r);}}
 static void range(std::vector<SfzRegion>& rows,int index,int low,int high,bool overlap,bool velocity=false){if(!juce::isPositiveAndBelow(index,(int)rows.size()))return;auto original=rows[index];int oldLow=velocity?original.lovel:original.low,oldHigh=velocity?original.hivel:original.high;int lower=0,upper=127,previous=-1,next=-1;for(int i=0;i<(int)rows.size();++i)if(i!=index){auto& r=rows[i];bool shared=velocity?!(r.high<original.low||r.low>original.high):!(r.hivel<original.lovel||r.lovel>original.hivel);if(!shared)continue;int a=velocity?r.lovel:r.low,b=velocity?r.hivel:r.high;if(b<oldLow&&(previous<0||b>(velocity?rows[previous].hivel:rows[previous].high)))previous=i;if(a>oldHigh&&(next<0||a<(velocity?rows[next].lovel:rows[next].low)))next=i;}
  if(!overlap){if(previous>=0)lower=(velocity?rows[previous].lovel:rows[previous].low)+1;if(next>=0)upper=(velocity?rows[next].hivel:rows[next].high)-1;}low=juce::jlimit(lower,upper,low);high=juce::jlimit(low,upper,high);
  if(!overlap)for(int i=0;i<(int)rows.size();++i)if(i!=index){auto& r=rows[i];bool shared=velocity?!(r.high<original.low||r.low>original.high):!(r.hivel<original.lovel||r.lovel>original.hivel);if(!shared)continue;int a=velocity?r.lovel:r.low,b=velocity?r.hivel:r.high;if(i==previous||(a<oldLow&&b>=low-1)){if(velocity)r.hivel=low-1;else r.high=low-1;}if(i==next||(b>oldHigh&&a<=high+1)){if(velocity)r.lovel=high+1;else r.low=high+1;}clamp(r);}
  auto& selected=rows[index];if(velocity){selected.lovel=low;selected.hivel=high;}else{selected.low=low;selected.high=high;}clamp(selected);
 }
 static void write(juce::XmlElement& parent,const std::vector<SfzRegion>& rows){auto* map=parent.createNewChildElement("multiMap");for(auto& r:rows){if(!r.source)continue;auto* x=map->createNewChildElement("region");x->setAttribute("source",LibraryStore::resolveFile(juce::File(r.source->path)).getFullPathName());x->setAttribute("root",r.root);x->setAttribute("low",r.low);x->setAttribute("high",r.high);x->setAttribute("velLow",r.lovel);x->setAttribute("velHigh",r.hivel);x->setAttribute("start",r.start);x->setAttribute("end",r.end);x->setAttribute("loopStart",r.loopStart);x->setAttribute("loopEnd",r.loopEnd);x->setAttribute("loopMode",r.loopMode);x->setAttribute("crossfadeMs",r.crossfadeMs);x->setAttribute("pingPong",r.pingPong);x->setAttribute("zeroSnap",r.zeroSnap);x->setAttribute("tune",r.tune);x->setAttribute("gain",r.gain);x->setAttribute("pan",r.pan);x->setAttribute("pitchConfidence",r.pitchConfidence);x->setAttribute("pitchMethod",r.pitchMethod);}}
 static SfzRegion read(const juce::XmlElement& x,std::shared_ptr<const AudioData> source){SfzRegion r;r.source=source;r.root=x.getIntAttribute("root",60);r.low=x.getIntAttribute("low");r.high=x.getIntAttribute("high",127);r.lovel=x.getIntAttribute("velLow");r.hivel=x.getIntAttribute("velHigh",127);r.start=x.getIntAttribute("start");r.end=x.getIntAttribute("end",-1);r.loopStart=x.getIntAttribute("loopStart");r.loopEnd=x.getIntAttribute("loopEnd",-1);r.loopMode=juce::jlimit(0,2,x.getIntAttribute("loopMode"));r.crossfadeMs=juce::jlimit(0.,1000.,x.getDoubleAttribute("crossfadeMs"));r.pingPong=x.getBoolAttribute("pingPong");r.zeroSnap=x.getBoolAttribute("zeroSnap");r.tune=juce::jlimit(-120.,120.,x.getDoubleAttribute("tune"));r.gain=juce::jlimit(0.,16.,x.getDoubleAttribute("gain",1));r.pan=juce::jlimit(-1.,1.,x.getDoubleAttribute("pan"));r.pitchConfidence=x.getDoubleAttribute("pitchConfidence");r.pitchMethod=x.getStringAttribute("pitchMethod");clamp(r);return r;}
};
